import { Service, MAX as LIMIT, cap, Level } from "./lib.decl"
const top = LIMIT
export output s: Service = { name: "a" }
export output t: Service = {
    name: "b"
}
const first = s.name
const c = cap(top)
const d = 250ms
type Local = Service { extra = name, level?: Level = "low" }
const m2 = std.math.min(top, 3)

type Circle = { kind: "circle", r: int }
type Rect = { kind: "rect", w: int, h: int }
type Shape = Circle | Rect
input shape: Shape
const area = if shape.kind == "circle" then shape.r * 2 else if shape.kind == "rect" then shape.w * shape.h else 0
const area2 = match shape {
    (c: Circle) => c.r * 2
    (r: Rect) => r.w * r.h
}
diagnostic wide(w: int) {
    severity = error
    message = `too wide: ${w}`
}
type Box = {
    w: int,
    h: int,
    area = w * h,
    big = area > 10,
    assert fits: w <= 100 else error `too wide: ${w}`,
    assert fits2: h <= 100 else wide(h)
}
